from pathlib import Path
from uuid import uuid5,NAMESPACE_URL
p=Path(__file__).resolve().parents[1]
def uid(key): return str(uuid5(NAMESPACE_URL,'tcc-demo:'+key))
def quote(v):
 if v is None:return 'NULL'
 if isinstance(v,bool):return 'TRUE' if v else 'FALSE'
 if isinstance(v,(int,float)):return str(v)
 return "'"+str(v).replace("'","''")+"'"
sql=['-- All values are fictitious. Generated by scripts/generate_demo_migration.py.']
def insert(table,cols,rows):
 if rows: sql.append('INSERT INTO '+table+' ('+','.join(cols)+') VALUES\n'+',\n'.join('('+','.join(map(quote,r))+')' for r in rows)+' ON CONFLICT DO NOTHING;')
insert('academic_terms',['id','starts_on','ends_on'],[('2025.2','2025-08-04','2025-12-12'),('2026.1','2026-02-02','2026-06-26'),('2026.2','2026-08-03','2026-12-04'),('2027.1','2027-02-01','2027-06-25')])
# Existing subjects retain their names and identifiers.
course=lambda i:f'b57cf5a4-bb33-4b37-9306-1c95b2ca{1000+i}'
subject=lambda i:f'8f5c7eb3-e2b4-4eff-a1b0-0e9f100000{i:02}'
student=lambda i:f'68580c37-69ca-4e35-b91f-3f010fbf9f{i:02}'
groups=[[1,2,3,4,5,6,28,29,30],[7,8,9,10,28,29,30],[11,12,13,14,29,30],[15,16,17,18,29,30],[19,20,21,22,27,29,30],[23,24,25,26,27,29,30]]
foundations=[['Introdução à Programação','Lógica Computacional','Matemática Discreta','Programação Orientada a Objetos','Interação Humano Computador','Computação em Nuvem'],['Introdução à Engenharia','Desenho Técnico','Física Aplicada','Materiais de Construção','Estruturas de Concreto','Construção Sustentável'],['Introdução à Administração','Economia','Contabilidade Básica','Gestão de Pessoas','Empreendedorismo','Gestão da Inovação'],['Introdução ao Direito','Ciência Política','Sociologia Jurídica','Direitos Humanos','Direito Digital','Mediação de Conflitos'],['Introdução à Psicologia','História da Psicologia','Psicologia Social','Processos Psicológicos Básicos','Psicologia Escolar','Psicologia do Trabalho'],['Introdução à Medicina','Biologia Celular','Histologia','Bioquímica','Saúde Coletiva','Comunicação em Saúde']]
subs=[];curr=[];pre=[]
for ci,items in enumerate(groups,1):
 c=course(ci)
 for k,name in enumerate(foundations[ci-1]):
  s=uid(f'foundation:{ci}:{k}')
  subs.append((s,name,'Docente demonstrativo',72,75,100))
  curr.append((c,s,1 if k<3 else 2 if k==3 else 6,'OPTIONAL' if k>=4 else 'REQUIRED',4))
 for k,si in enumerate(items):curr.append((c,subject(si),3+k//2,'REQUIRED',2 if si in (29,30) else 4))
 pre.append((c,subject(items[0]),uid(f'foundation:{ci}:0')))
 if ci==1:
  pre.extend([(c,subject(2),uid('foundation:1:0')),(c,subject(6),subject(2))])
insert('subjects',['id','name','teacher','workload_hours','minimum_attendance_percentage','class_duration_minutes'],subs)
insert('course_curriculum',['course_id','subject_id','recommended_semester','category','credits'],curr)
insert('subject_prerequisites',['course_id','subject_id','prerequisite_id'],pre)
# Legacy grade rows become individual results of current attempts (no data is deleted).
sql.append("INSERT INTO academic_attempts(id,student_id,subject_id,term_id,assessment_model,attendance_percentage) SELECT md5('current:'||ss.student_id::text||ss.subject_id::text)::uuid,ss.student_id,ss.subject_id,'2026.2',COALESCE(am.model_type,'AV_SERIES'),ss.current_attendance_percentage FROM student_subjects ss LEFT JOIN assessment_models am ON am.subject_id=ss.subject_id ON CONFLICT DO NOTHING;")
sql.append("UPDATE student_grades g SET attempt_id=a.id FROM academic_attempts a WHERE a.student_id=g.student_id AND a.subject_id=g.subject_id AND a.term_id='2026.2' AND g.attempt_id IS NULL;")
# Every current subject has all assessment slots; NULL means not yet published, zero remains zero.
sql.append("INSERT INTO student_grades(id,student_id,subject_id,attempt_id,assessment_name,grade_value) SELECT md5(a.id::text||n.name)::uuid,a.student_id,a.subject_id,a.id,n.name,NULL FROM academic_attempts a CROSS JOIN (VALUES ('AV1'),('AV2'),('AV3'),('NOTA_UNICA')) n(name) WHERE (a.assessment_model='AV_SERIES' AND n.name<>'NOTA_UNICA') OR (a.assessment_model='SINGLE_GRADE' AND n.name='NOTA_UNICA') ON CONFLICT(attempt_id,assessment_name) DO NOTHING;")
# Mixed scenarios on current subjects with no previous notes, without overwriting imported grades.
sql.append("UPDATE student_grades g SET grade_value=CASE WHEN g.assessment_name='AV1' THEN 6 WHEN g.assessment_name='AV2' THEN 7 ELSE NULL END FROM academic_attempts a WHERE g.attempt_id=a.id AND g.grade_value IS NULL AND a.assessment_model='AV_SERIES' AND g.assessment_name IN ('AV1','AV2') AND a.subject_id NOT IN ('8f5c7eb3-e2b4-4eff-a1b0-0e9f10000002');")
attempts=[];grades=[]
for ci in range(1,7):
 for offset in range(2):
  si=(ci-1)*2+1+offset; st=student(si)
  for k in range(4):
   sub=uid(f'foundation:{ci}:{k}'); term='2025.2' if k<2 else '2026.1'; a=uid(f'attempt:{si}:{k}')
   attempts.append((a,st,sub,term,'AV_SERIES',90 if not(offset and k==2) else 70,True))
   vals=([7,8,8] if k<2 else [8,8,9]) if offset==0 else ([3,4,None] if k==0 else [6,6,3] if k==1 else [7,7,6])
   for n,v in zip(['AV1','AV2','AV3'],vals):grades.append((uid(a+n),st,sub,a,n,v))
insert('academic_attempts',['id','student_id','subject_id','term_id','assessment_model','attendance_percentage','closed'],attempts)
insert('student_grades',['id','student_id','subject_id','attempt_id','assessment_name','grade_value'],grades)
# Repeat failed introduction for the second student of each course.
attempts=[];grades=[]
for ci in range(1,7):
 st=student(ci*2);sub=uid(f'foundation:{ci}:0');a=uid(f'repeat:{ci}')
 attempts.append((a,st,sub,'2026.1','AV_SERIES',95,True))
 for n,v in zip(['AV1','AV2','AV3'],[8,8,8]):grades.append((uid(a+n),st,sub,a,n,v))
insert('academic_attempts',['id','student_id','subject_id','term_id','assessment_model','attendance_percentage','closed'],attempts)
insert('student_grades',['id','student_id','subject_id','attempt_id','assessment_name','grade_value'],grades)
# Per-course teachers, rooms and schedules; no claim these are real university offerings.
offerings=[];schedules=[]
for c,s,sem,cat,credits in curr:
 for term in ['2026.2','2027.1']:
  o=uid(f'offering:{c}:{s}:{term}');ix=len(offerings)
  offerings.append((o,c,s,term,'A','Docente demonstrativo','Bloco D / sala '+str(100+ix%20),0 if ix%9==0 else 12+ix%15))
  day=ix%5+1;start='18:30' if ix%2==0 else '20:20';end='20:10' if ix%2==0 else '22:00'
  schedules.append((uid(o+'schedule'),o,day,start,end))
insert('subject_offerings',['id','course_id','subject_id','term_id','class_code','teacher','room','seats_available'],offerings)
insert('offering_schedules',['id','offering_id','weekday','starts_at','ends_at'],schedules)
sql.append("UPDATE subject_offerings o SET teacher=s.teacher FROM subjects s WHERE s.id=o.subject_id;")
sql.append("INSERT INTO student_offerings(student_id,offering_id) SELECT ss.student_id,o.id FROM student_subjects ss JOIN students st ON st.id=ss.student_id JOIN subject_offerings o ON o.subject_id=ss.subject_id AND o.course_id=st.course_id AND o.term_id='2026.2' ON CONFLICT DO NOTHING;")
sql.append("UPDATE assessment_models SET av3_has_greater_weight=FALSE, formula_description='Regra do protótipo: MI=(AV1+AV2)/2 >=4, AV3 obrigatória >=4, MF=(MI+AV3)/2 >=5, frequência mínima exigida.' WHERE model_type='AV_SERIES';")
# New official-looking claims are avoided by documenting fixture requirements as a partial demonstration matrix.
sql.append("INSERT INTO academic_events(id,title,event_type,starts_on,ends_on,audience,description) VALUES ('"+uid('av3-2026.2')+"','AV3 — calendário fictício','EXAM_PERIOD','2026-11-23','2026-12-02','Graduação','Datas demonstrativas do TCC, não oficiais'),('"+uid('enroll-2027.1')+"','Matrícula 2027.1 — calendário fictício','ENROLLMENT','2027-01-11','2027-01-29','Graduação','Datas demonstrativas do TCC, não oficiais');")
(p/'migrations/V8__seed_academic_expansion.sql').write_text('\n\n'.join(sql)+'\n')
